```
{
  "title": "Update EU database of processing factors",
  "abstract": "This report presents an update of the European Union (EU) database of processing factors for pesticide residues in food. The database was extended with respect to considered processes and processed commodities, while some commodities were not included due to their composite nature or edible peel.",
  "recommendations": [
    {
      "text": "Establish a mechanism for regular updates of the EU database of processing factors",
      "description": "New studies are conducted and submitted continuously, and residue definitions keep changing."
    },
    {
      "text": "Align raw commodity categories used with respect to storage stability and analytical methods",
      "description": "This should be kept in mind when updating the respective OECD guideline and guidance document."
    },
    {
      "text": "Improve transparency and traceability of processing studies underlying a PF",
      "description": "Unambiguous study citations (title, author, year, study number) were often missing for processing studies evaluated in EFSA’s Reasoned Opinions and in the underlying Evaluation Reports."
    },
    {
      "text": "Provide a sufficient number of independent processing trials when setting up a study",
      "description": "This is necessary to provide a reliable median PF output."
    },
    {
      "text": "Discuss the current minimum requirement of 2 studies (sufficient if variability is < 50%) or 3 studies (required if variability of results in 2 studies is > 50% )",
      "description": "This is necessary to yield reliable median factors."
    }
  ],
  "future_development": [
    {
      "text": "Extend the processing database by including physico-chemical properties of active substances",
      "description": "This would allow for comparison with and maybe even for extrapolation to other compounds."
    },
    {
      "text": "Establish a set of quality criteria for drying factors",
      "description": "A list of suitable factors should be provided together with recommendations for extrapolation."
    }
  ]
}
```

